import{_ as i,c as o,o as a,aj as r}from"./chunks/framework.CDhdelVI.js";const p=JSON.parse('{"title":"Proofing","description":"Practical proofing guide for shaped dough: readiness signs, timing control, and how to avoid under- or over-proofing.","frontmatter":{"title":"Proofing","description":"Practical proofing guide for shaped dough: readiness signs, timing control, and how to avoid under- or over-proofing.","head":[["meta",{"name":"description","content":"Practical proofing guide for shaped dough: readiness signs, timing control, and how to avoid under- or over-proofing."}],["meta",{"property":"og:title","content":"Proofing"}],["meta",{"property":"og:description","content":"Practical proofing guide for shaped dough: readiness signs, timing control, and how to avoid under- or over-proofing."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/proofing.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Proofing"}],["meta",{"name":"twitter:description","content":"Practical proofing guide for shaped dough: readiness signs, timing control, and how to avoid under- or over-proofing."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/proofing.html"}]]},"headers":[],"relativePath":"guides/proofing.md","filePath":"guides/proofing.md"}'),n={name:"guides/proofing.md"};function t(s,e,l,d,g,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="proofing" tabindex="-1">Proofing <a class="header-anchor" href="#proofing" aria-label="Permalink to “Proofing”">​</a></h1><p>Proofing is the final rise after shaping. Its job is simple: finish gas development without losing structure.</p><div class="guide-glance"><div class="guide-glance-card"><strong>Best For</strong><span>Checking whether shaped dough is ready to bake without guessing.</span></div><div class="guide-glance-card"><strong>Focus</strong><span>Readiness tests, timing control, and under- vs over-proofing.</span></div><div class="guide-glance-card"><strong>Read This Next</strong><span>Fermentation if you want to connect bulk and final-rise decisions.</span></div></div><h2 id="what-good-proofing-looks-like" tabindex="-1">What Good Proofing Looks Like <a class="header-anchor" href="#what-good-proofing-looks-like" aria-label="Permalink to “What Good Proofing Looks Like”">​</a></h2><ul><li>Dough gains volume and feels lighter</li><li>Surface is slightly puffy, not flat and slack</li><li>Internal gas is present, but shape still holds</li></ul><h2 id="basic-workflow" tabindex="-1">Basic Workflow <a class="header-anchor" href="#basic-workflow" aria-label="Permalink to “Basic Workflow”">​</a></h2><ol><li>Shape with enough surface tension.</li><li>Place dough in tray, pan, banneton, or seam-side rest position.</li><li>Cover to prevent skinning.</li><li>Proof at room temp or cold, based on style and schedule.</li><li>Bake when dough is expanded and responsive, not exhausted.</li></ol><h2 id="readiness-checks" tabindex="-1">Readiness Checks <a class="header-anchor" href="#readiness-checks" aria-label="Permalink to “Readiness Checks”">​</a></h2><ul><li><strong>Finger dent test</strong>: <ul><li>springs back immediately: under-proofed</li><li>springs back slowly and partially: close to ready</li><li>stays fully indented and weak: over-proofed</li></ul></li><li><strong>Lift test</strong>: shaped pieces feel airy for their size</li><li><strong>Visual test</strong>: clear expansion without tearing or collapse</li></ul><h2 id="under-vs-over-proofing" tabindex="-1">Under vs Over Proofing <a class="header-anchor" href="#under-vs-over-proofing" aria-label="Permalink to “Under vs Over Proofing”">​</a></h2><ul><li><strong>Under-proofed</strong>: <ul><li>tight crumb, random ruptures, dense center</li><li>strong oven spring but poor shape control</li></ul></li><li><strong>Over-proofed</strong>: <ul><li>weak lift, spreading, pale bake, fragile structure</li><li>little oven spring, easy collapse</li></ul></li></ul><h2 id="timing-control" tabindex="-1">Timing Control <a class="header-anchor" href="#timing-control" aria-label="Permalink to “Timing Control”">​</a></h2><ul><li>Warmer dough and warmer room speed proofing.</li><li>Higher yeast percentages speed proofing.</li><li>Colder dough and lower yeast slow proofing.</li></ul><p>For better consistency, keep your dough temperature and container setup repeatable.</p><h2 id="practical-fixes" tabindex="-1">Practical Fixes <a class="header-anchor" href="#practical-fixes" aria-label="Permalink to “Practical Fixes”">​</a></h2><ul><li><strong>Running late</strong>: move proof to a slightly warmer spot</li><li><strong>Running early</strong>: move proof to cooler conditions or fridge</li><li><strong>Surface drying</strong>: cover better; skinning blocks expansion</li><li><strong>Weak shape during proof</strong>: tighten shaping next batch and shorten final proof slightly</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/fermentation.html">Fermentation</a></li><li><a href="/guides/no-knead-vs-kneading.html">No-Knead vs Kneading</a></li><li><a href="/guides/hydration.html">Hydration</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div>',20)])])}const u=i(n,[["render",t]]);export{p as __pageData,u as default};
